const libraryData = [
{id:"brain",title:"كيف يعمل الدماغ؟",track:"science",category:"العلوم الطبيعية والفيزيائية",desc:"تعرف كيف يستقبل الدماغ المعلومات، وكيف تساعد الخلايا العصبية والذاكرة على التعلم.",summary:"الدماغ مركز استقبال المعلومات ومعالجتها وتنسيق الاستجابات. ستتعرف على الخلايا العصبية والذاكرة، ولماذا يساعد النوم والتكرار على التعلم.",level:"علوم الحياة",stage:"إعدادي",lesson:"كيف يعمل الدماغ؟",time:"8 دقائق",body:"الدماغ جزء أساسي من الجهاز العصبي؛ يستقبل المعلومات من الحواس، ويعالجها، ويساعد الجسم على اختيار الاستجابة المناسبة.\n\nالخلايا العصبية تنقل المعلومات بإشارات كهربائية وكيميائية، وتتواصل عبر وصلات تسمى المشابك العصبية.\n\nتوجد أشكال مختلفة للذاكرة، منها ذاكرة قصيرة المدى وذاكرة طويلة المدى. ويساعد التكرار المتباعد والنوم والراحة على تثبيت ما نتعلمه.\n\nعندما نتدرب تتغير قوة الاتصالات بين بعض الخلايا العصبية. جرّب شرح فكرة تعلمتها اليوم بكلماتك، ثم راجعها في اليوم التالي."},
{id:"renewable",title:"الطاقة المتجددة",track:"science",category:"العلوم الطبيعية والفيزيائية",desc:"اكتشف الطاقة الشمسية والرياح والمياه، وكيف تتحول إلى كهرباء.",summary:"تأتي الطاقة المتجددة من مصادر تتجدد طبيعياً مثل الشمس والرياح والمياه. ستتعرف على طرق إنتاج الكهرباء منها، وعلى فوائدها وتحدياتها.",level:"علوم البيئة",stage:"ثانوي",lesson:"الطاقة المتجددة",time:"8 دقائق",body:"الطاقة المتجددة تأتي من مصادر تتجدد طبيعياً، وتساعد على تنويع مصادر الطاقة وتقليل الاعتماد على الوقود الأحفوري.\n\nتحول الألواح الكهروضوئية ضوء الشمس مباشرة إلى كهرباء. ويحوّل التوربين الهوائي حركة الرياح إلى طاقة ميكانيكية يشغل بها مولداً كهربائياً.\n\nتستفيد محطات الطاقة المائية من حركة المياه أو فرق الارتفاع لتشغيل التوربينات. وتوجد أيضاً تقنيات تستفيد من حرارة باطن الأرض والمواد العضوية.\n\nلكل مصدر تحديات؛ فالإنتاج الشمسي والرياح يتغير مع الطقس والوقت، وقد تؤثر بعض المشاريع في النظم البيئية. لذلك يوازن التخطيط الجيد بين الفوائد والآثار."},
{id:"physics-world",title:"الفيزياء من حولنا",track:"science",category:"العلوم الطبيعية والفيزيائية",desc:"افهم الحركة والقوى والطاقة والضوء من خلال مواقف الحياة اليومية.",summary:"تفسر الفيزياء كثيراً مما نراه كل يوم: حركة الدراجة، سقوط الأشياء، انعكاس الضوء وانتقال الحرارة. ستربط المفاهيم العلمية بأمثلة بسيطة من محيطك.",level:"فيزياء",stage:"إعدادي",lesson:"الفيزياء من حولنا",time:"9 دقائق",body:"تدرس الفيزياء المادة والطاقة والحركة والقوى، وتحاول تفسير الظواهر الطبيعية بقوانين يمكن اختبارها.\n\nعندما تدفع عربة تتغير حركتها بحسب القوة المؤثرة وكتلتها. وتصف قوانين نيوتن العلاقة بين القوة والحركة؛ فالقوة المحصلة تساوي الكتلة مضروبة في التسارع.\n\nتنتقل الحرارة من الجسم الأعلى حرارة إلى الأقل حرارة، ويمكن أن تنتقل بالتوصيل أو الحمل أو الإشعاع.\n\nينعكس الضوء عن الأسطح، وينكسر عندما ينتقل بين وسطين مختلفين. راقب ملعقة داخل كأس ماء ولاحظ كيف يبدو شكلها عند سطح الماء."},
{id:"ai",title:"أساسيات الذكاء الاصطناعي",track:"technology",category:"التقنية والذكاء الاصطناعي",desc:"تعرف على البيانات والنماذج والتعلم الآلي واستخدامات الذكاء الاصطناعي.",summary:"الذكاء الاصطناعي يساعد الأنظمة على تنفيذ مهام مثل فهم اللغة والتعرف على الأنماط. ستفهم دور البيانات والتدريب والنماذج، ولماذا قد تخطئ النتائج.",level:"تقنية",stage:"ثانوي",lesson:"أساسيات الذكاء الاصطناعي",time:"10 دقائق",body:"الذكاء الاصطناعي مجال يطوّر أنظمة تنفذ مهاماً مثل التعرف على الأنماط وفهم اللغة والتنبؤ.\n\nالبيانات هي الأمثلة والمعلومات التي يتعلم منها النظام. والتعلم الآلي طريقة لاكتشاف الأنماط من البيانات بدلاً من كتابة كل قاعدة يدوياً.\n\nالنموذج هو ما ينتج عن التدريب، ويستخدم لتقديم توقع أو إجابة عند إدخال بيانات جديدة. وتؤثر جودة البيانات وتنوعها في جودة النتائج.\n\nقد يخطئ النموذج أو يعكس تحيزات موجودة في البيانات؛ تحقق من المعلومات المهمة، واحمِ خصوصيتك ولا تشارك بياناتك الحساسة."},
{id:"security",title:"أمن المعلومات",track:"technology",category:"التقنية والذكاء الاصطناعي",desc:"تعلم حماية الحسابات وكلمات المرور والبيانات من المخاطر الشائعة.",summary:"أمن المعلومات يعني حماية الحسابات والأجهزة والبيانات. ستتعرف على كلمات المرور القوية والمصادقة المتعددة وكيفية تمييز رسائل الاحتيال.",level:"أمن رقمي",stage:"ثانوي",lesson:"أساسيات أمن المعلومات",time:"8 دقائق",body:"أمن المعلومات هو حماية البيانات والأجهزة والحسابات من الوصول أو التغيير أو الإتلاف غير المصرح به.\n\nاستخدم كلمة مرور طويلة وفريدة لكل حساب، وفعّل المصادقة متعددة العوامل متى توفرت. لا تستخدم كلمة المرور نفسها في مواقع مختلفة.\n\nاحذر الرسائل التي تستعجلك للنقر أو تطلب كلمة المرور أو رمز التحقق. تحقق من عنوان الموقع والمرسل قبل فتح الروابط أو الملفات.\n\nحدّث النظام والتطبيقات، واحتفظ بنسخة احتياطية من ملفاتك المهمة. لا تشارك رموز الدخول مع أي شخص، حتى لو ادعى أنه من الدعم الفني."},
{id:"programming-basics",title:"أساسيات البرمجة",track:"technology",category:"التقنية والذكاء الاصطناعي",desc:"اكتشف الخوارزميات والمتغيرات والشروط والتكرار من خلال أمثلة سهلة.",summary:"البرمجة هي كتابة تعليمات واضحة ليعالج الحاسوب مهمة محددة. ستتعرف على الخوارزمية والمتغير والشرط والتكرار، وهي لبنات بناء البرامج.",level:"برمجة",stage:"إعدادي",lesson:"أساسيات البرمجة",time:"10 دقائق",body:"تبدأ البرمجة بتحديد مشكلة ثم وصف خطوات حلها. تسمى هذه الخطوات المرتبة خوارزمية، ويمكن تمثيلها بالكلمات أو المخططات قبل كتابة الكود.\n\nالمتغير مكان يحمل قيمة يمكن للبرنامج استخدامها أو تغييرها، مثل اسم المستخدم أو نتيجة عملية حسابية.\n\nتسمح الجملة الشرطية بتنفيذ تعليمات عند تحقق شرط معين؛ مثل: إذا كانت الإجابة صحيحة فاعرض رسالة نجاح.\n\nتكرر الحلقات مجموعة تعليمات أكثر من مرة، وهذا يوفر كتابة الأوامر المتشابهة يدوياً. ابدأ بمثال صغير، واختبره، ثم أصلح الأخطاء تدريجياً."},
{id:"primes",title:"الأعداد الأولية",track:"math",category:"الرياضيات والمنطق",desc:"افهم الأعداد الأولية وطرق تحليل الأعداد واستخداماتها الرياضية.",summary:"العدد الأولي لا يقبل القسمة دون باقٍ إلا على 1 وعلى نفسه. ستتعلم كيف تميّزه وتحلل الأعداد إلى عوامل أولية، ولماذا تظهر هذه الأعداد في التشفير.",level:"رياضيات",stage:"إعدادي",lesson:"الأعداد الأولية",time:"7 دقائق",body:"العدد الأولي عدد صحيح أكبر من 1 لا يقبل القسمة دون باقٍ إلا على 1 وعلى نفسه. أمثلة: 2 و3 و5 و7 و11. العدد 2 هو العدد الأولي الزوجي الوحيد، والعدد 1 ليس أولياً.\n\nيمكن اختبار عدد صغير بالقسمة على الأعداد الأولية حتى جذره التربيعي؛ فإذا لم يقبل القسمة على أي منها فهو أولي.\n\nكل عدد صحيح أكبر من 1 يمكن تحليله إلى حاصل ضرب أعداد أولية. مثال: 30 = 2 × 3 × 5.\n\nتدخل خصائص الأعداد الأولية في بعض أنظمة التشفير، حيث تساعد العمليات على أعداد كبيرة في بناء مفاتيح رياضية."},
{id:"geometry",title:"الهندسة في الحياة اليومية",track:"math",category:"الرياضيات والمنطق",desc:"اكتشف الأشكال والقياسات والزوايا والمساحات في محيطك.",summary:"تساعدنا الهندسة على فهم الأشكال والمسافات والأحجام. ستتعرف على المثلث والمستطيل والدائرة، وتستخدم قواعد بسيطة لقياس أشياء حولك.",level:"رياضيات",stage:"ابتدائي",lesson:"الهندسة في الحياة اليومية",time:"7 دقائق",body:"تدرس الهندسة الأشكال والأحجام والمواقع والعلاقات بين الخطوط والزوايا، ونستخدمها في البناء والتصميم والخرائط.\n\nللمثلث ثلاثة أضلاع، ومجموع زواياه الداخلية 180 درجة. أما مساحة المستطيل فتساوي الطول مضروباً في العرض.\n\nفي الدائرة تبعد كل نقطة على المحيط المسافة نفسها عن المركز، وتسمى هذه المسافة نصف القطر.\n\nابحث حولك عن نافذة مستطيلة أو إشارة مثلثة أو ساعة دائرية، وحاول قياس أبعادها."},
{id:"math-puzzles",title:"ألغاز رياضية ومنطقية",track:"math",category:"الرياضيات والمنطق",desc:"درّب عقلك على الأنماط والاستنتاج وحل المشكلات خطوة بخطوة.",summary:"تساعد الألغاز على تدريب الملاحظة وتنظيم التفكير واختبار الفرضيات. ستتعلم البحث عن النمط وتجزئة المسألة بدلاً من التخمين السريع.",level:"منطق",stage:"ابتدائي",lesson:"ألغاز رياضية ومنطقية",time:"6 دقائق",body:"ابدأ بقراءة اللغز بهدوء، وحدد ما تعرفه وما تحتاج إلى اكتشافه. لا تتسرع في اختيار أول إجابة تبدو مناسبة.\n\nابحث عن الأنماط في الأعداد أو الأشكال. إذا كان التسلسل 2، 4، 6، 8، فالزيادة كل مرة تساوي 2، ولذلك العدد التالي هو 10.\n\nجرّب حالات صغيرة، وارسم جدولاً أو شكلاً إذا كانت المسألة تتضمن علاقات متعددة.\n\nبعد الوصول إلى الحل، تحقق من أنه يحقق جميع شروط السؤال، ثم اشرح كيف وصلت إليه لشخص آخر."},
{id:"critical",title:"التفكير النقدي",track:"humanities",category:"الإنسانيات واللغات",desc:"قيّم الأدلة واكتشف المغالطات وابنِ استنتاجات منطقية.",summary:"التفكير النقدي هو فحص الادعاءات والأدلة قبل تصديقها. ستتعلم طرح الأسئلة ومقارنة المصادر والتمييز بين الارتباط والسببية.",level:"مهارات",stage:"ثانوي",lesson:"التفكير النقدي",time:"8 دقائق",body:"التفكير النقدي هو فحص المعلومات والأدلة قبل قبول الادعاء أو رفضه، مع الاستعداد لتعديل الرأي عند ظهور دليل أقوى.\n\nاسأل: من نشر المعلومة؟ ما خبرته؟ هل يذكر مصدراً؟ وهل توجد أدلة مستقلة تدعم النتيجة؟\n\nميّز بين الارتباط والسببية؛ فحدوث أمرين معاً لا يثبت أن أحدهما سبب الآخر. وانتبه للمغالطات، مثل مهاجمة الشخص بدلاً من مناقشة حجته.\n\nتدريب: اختر ادعاءً تقرؤه اليوم، واكتب دليلاً يؤيده ودليلاً قد يضعفه، ثم قيّم موثوقية المصدر."},
{id:"language",title:"كيف نتعلم لغة جديدة؟",track:"humanities",category:"الإنسانيات واللغات",desc:"نظّم تعلم المفردات والاستماع والتحدث والقراءة والمراجعة.",summary:"يتقدم تعلم اللغة بالممارسة المنتظمة واستخدام الكلمات في سياقها. ستبني روتيناً يجمع المفردات والاستماع والتحدث والقراءة والمراجعة.",level:"لغات",stage:"ابتدائي",lesson:"كيف نتعلم لغة جديدة؟",time:"9 دقائق",body:"يتحسن تعلم اللغة بالممارسة المنتظمة واستخدام الكلمات في سياقات حقيقية، وليس بحفظ القواعد وحدها.\n\nتعلم المفردات داخل جمل قصيرة وراجعها على فترات متباعدة حتى يسهل تذكرها.\n\nاستمع يومياً إلى مقاطع مناسبة لمستواك، وأعد المقطع القصير لملاحظة النطق والتعبير. اقرأ نصوصاً بسيطة، وحاول فهم المعنى العام قبل البحث عن كل كلمة.\n\nتحدث بصوت مرتفع حتى لو كنت وحدك، واكتب بضعة أسطر يومياً. خطة بداية مناسبة: عشر دقائق للمفردات، وعشر دقائق للاستماع، وخمس دقائق للتحدث."},
{id:"carthage",title:"الحضارة القرطاجية",track:"humanities",category:"الإنسانيات واللغات",desc:"تعرف على نشأة قرطاج وموقعها التجاري وعلاقتها بروما.",summary:"نشأت قرطاج قرب مدينة تونس الحالية، وأصبحت مركزاً بحرياً وتجارياً مهماً في المتوسط. ستتعرف على توسعها والحروب البونية وأثرها في تاريخ المنطقة.",level:"تاريخ",stage:"إعدادي",lesson:"الحضارة القرطاجية",time:"9 دقائق",body:"نشأت قرطاج على الساحل الشمالي لإفريقيا قرب مدينة تونس الحالية، وتطورت إلى مركز تجاري وبحري مهم في غرب البحر المتوسط. وتنسب الروايات القديمة تأسيسها إلى مستوطنين فينيقيين من مدينة صور.\n\nساعد موقعها وموانئها وشبكاتها التجارية على بناء نفوذ واسع. وامتد نشاطها عبر أجزاء من سواحل المتوسط وشمال إفريقيا.\n\nخاضت قرطاج وروما الحروب البونية، واشتهر القائد حنبعل بعبوره جبال الألب خلال الحرب البونية الثانية.\n\nدمرت روما قرطاج سنة 146 قبل الميلاد، ثم أعيد تأسيس المدينة في العصر الروماني. وتبقى آثار قرطاج شاهداً مهماً على تاريخ تونس والمتوسط."},
{id:"molecular-genetics",title:"مبادئ الوراثة الجزيئية",track:"science",category:"العلوم الطبيعية والفيزيائية",desc:"افهم كيف تحمل الجينات المعلومات الوراثية وكيف تستخدمها الخلايا.",summary:"تشرح الوراثة الجزيئية كيف يخزن الحمض النووي المعلومات وكيف تستعمل الخلية هذه التعليمات. ستتعرف على تضاعف DNA والنسخ والترجمة وتنظيم التعبير الجيني.",level:"أحياء جزيئية",stage:"جامعي",lesson:"مبادئ الوراثة الجزيئية",time:"12 دقيقة",body:"يحمل الحمض النووي DNA المعلومات الوراثية في تسلسل من القواعد النيتروجينية. ويحتوي الجين على مقطع من DNA يمكن أن يسهم في إنتاج جزيء وظيفي مثل RNA أو بروتين.\n\nقبل انقسام الخلية يتضاعف DNA بطريقة شبه محافظة؛ إذ يحتوي كل جزيء جديد على شريط قديم وآخر جرى بناؤه حديثاً.\n\nفي عملية النسخ تستخدم الخلية أحد شريطي DNA قالباً لإنتاج RNA. وفي الترجمة تقرأ الريبوسومات الشفرة الموجودة في RNA الرسول وتربط الأحماض الأمينية لتكوين البروتين.\n\nلا تعمل كل الجينات في كل الخلايا وفي كل الأوقات؛ إذ ينظم التعبير الجيني بحسب نوع الخلية والظروف والإشارات. وقد تؤثر الطفرات في تسلسل DNA ونتائج عمل الجين."},
{id:"deep-learning",title:"التعلم العميق والشبكات العصبية",track:"technology",category:"التقنية والذكاء الاصطناعي",desc:"تعرف على طبقات الشبكات العصبية والتدريب والتعميم ومخاطر فرط التكيّف.",summary:"التعلم العميق فرع من التعلم الآلي يستخدم شبكات عصبية متعددة الطبقات لاكتشاف أنماط معقدة. ستتعرف على الأوزان ودالة الخسارة والتدريب وفرط التكيّف.",level:"ذكاء اصطناعي متقدم",stage:"جامعي",lesson:"التعلم العميق والشبكات العصبية",time:"14 دقيقة",body:"تتكون الشبكة العصبية الاصطناعية من وحدات حسابية مترابطة ترتب غالباً في طبقة إدخال وطبقات مخفية وطبقة إخراج. تنقل الوحدات القيم وتحولها باستخدام أوزان ودوال تنشيط.\n\nأثناء التدريب تقارن الشبكة مخرجاتها بالقيم المستهدفة عبر دالة خسارة تقيس مقدار الخطأ. ثم تعدل الأوزان باستخدام خوارزميات تحسين مثل الانحدار المتدرج والانتشار العكسي.\n\nلا يكفي أن تحقق الشبكة أداءً عالياً على بيانات التدريب؛ ينبغي اختبارها على بيانات لم تستخدم في التدريب لقياس قدرتها على التعميم.\n\nيحدث فرط التكيّف عندما تتعلم الشبكة تفاصيل وضوضاء بيانات التدريب أكثر من الأنماط العامة. ويساعد تنويع البيانات والتحقق المنفصل والتنظيم على الحد منه."},
{id:"statistics",title:"مقدمة في الإحصاء والاحتمالات",track:"math",category:"الرياضيات والمنطق",desc:"حلل البيانات وافهم التشتت والاحتمالات والتفسير الإحصائي.",summary:"يوفر الإحصاء أدوات لوصف البيانات والاستدلال منها، بينما تقيس الاحتمالات عدم اليقين. ستتعرف على المتوسط والتشتت والحدث العشوائي وحدود الاستنتاج.",level:"إحصاء",stage:"جامعي",lesson:"مقدمة في الإحصاء والاحتمالات",time:"13 دقيقة",body:"يصف الإحصاء البيانات ويلخصها، ثم يستخدم عينات من المجتمع لدراسة أسئلة أوسع. يبدأ التحليل بفحص نوع البيانات وطريقة جمعها ومدى تمثيل العينة للمجتمع.\n\nالمتوسط الحسابي يساوي مجموع القيم مقسوماً على عددها، بينما يمثل الوسيط القيمة الوسطى بعد ترتيب البيانات. ويصف التباين والانحراف المعياري مقدار انتشار القيم حول المتوسط.\n\nتقيس الاحتمالات مدى إمكانية وقوع حدث. وعندما تكون النتائج متساوية الإمكان، يساوي احتمال الحدث عدد النتائج الملائمة مقسوماً على عدد النتائج الممكنة.\n\nلا يثبت الارتباط وحده وجود علاقة سببية، وقد تتأثر النتائج بتحيز العينة أو طريقة القياس. لذلك ينبغي عرض حجم العينة والافتراضات ومقدار عدم اليقين عند تفسير النتائج."},
{id:"historical-methods",title:"مناهج البحث التاريخي",track:"humanities",category:"الإنسانيات واللغات",desc:"تعلم نقد المصادر التاريخية ومقارنتها وبناء تفسير مدعوم بالأدلة.",summary:"البحث التاريخي لا يكتفي بسرد الأحداث؛ بل يفحص المصادر وسياقها ويقارن الشهادات لبناء تفسير قابل للمراجعة. ستتعرف على المصدر الأولي والنقد الداخلي والخارجي.",level:"منهجية بحث",stage:"جامعي",lesson:"مناهج البحث التاريخي",time:"12 دقيقة",body:"يبدأ البحث التاريخي بسؤال محدد يساعد على اختيار المصادر والفترة الزمنية والمجال الجغرافي المناسب.\n\nقد يكون المصدر أولياً إذا نشأ في زمن الحدث أو على صلة مباشرة به، مثل رسالة أو سجل أو قطعة أثرية. أما المصدر الثانوي فيحلل الأدلة السابقة ويقدم تفسيراً لها.\n\nيفحص النقد الخارجي أصالة المصدر وتاريخه ومؤلفه وسلامة نسبته، بينما يدرس النقد الداخلي محتواه وغرضه والجمهور الذي وُجه إليه والظروف التي كُتب فيها.\n\nتُقارن المصادر المستقلة وتُرتب الوقائع زمنياً، ثم يبنى التفسير مع التمييز بين ما تثبته الأدلة وما يبقى احتمالاً. ويجب ذكر حدود المصادر وتجنب إسقاط مفاهيم الحاضر على الماضي دون تفسير."}
];
