let timerEnd=0;
function displayTimer(){const m=Math.floor(timerSeconds/60),s=timerSeconds%60;$("#timerDisplay").textContent=String(m).padStart(2,"0")+":"+String(s).padStart(2,"0");$("#miniTimer").textContent=String(m).padStart(2,"0")+":"+String(s).padStart(2,"0");const total=timerTotalSeconds;const elapsed=Math.max(0,total-timerSeconds);const deg=Math.max(0,Math.min(360,elapsed/total*360));$("#timerRing").style.background="conic-gradient(var(--purple) 0deg "+deg+"deg, #9a72ff1b "+deg+"deg 360deg)";}
function stopTimer(){if(timerInterval){clearInterval(timerInterval);timerInterval=null;}$("#timerStart").textContent="استئناف";}
function startTimer(){if(timerInterval){stopTimer();return;}if(timerSeconds<=0)timerSeconds=timerMode==="focus"?1500:300;timerEnd=Date.now()+timerSeconds*1000;$("#timerStart").textContent="إيقاف مؤقت";$("#timerMessage").textContent="";timerInterval=setInterval(()=>{timerSeconds=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));displayTimer();if(timerSeconds<=0){stopTimer();$("#timerMessage").textContent=timerMode==="focus"?"أحسنت! انتهت جلسة التركيز. خذ استراحة.":"انتهت الاستراحة. أنت جاهز لجلسة جديدة.";if(timerMode==="focus"){progress.minutes+=25;store.set("progress",progress);renderProgress();}showToast("انتهى المؤقت!");}},250);}
function resetTimer(minutes,mode){stopTimer();timerMode=mode||"focus";timerSeconds=(minutes||25)*60;timerTotalSeconds=timerSeconds;$("#timerMode").textContent=timerMode==="focus"?"وقت التركيز":"وقت الاستراحة";$("#timerStart").textContent="ابدأ";$("#timerMessage").textContent="";$$(".preset").forEach(b=>b.classList.toggle("active",Number(b.dataset.minutes)===(minutes||25)));displayTimer();}
function calculate(expression){const tokens=expression.replace(/×/g,"*").replace(/÷/g,"/").replace(/−/g,"-").match(/(?:\d+\.?\d*|\.\d+|[()+\-*/])/g);if(!tokens||tokens.join("")!==expression.replace(/\s/g,"").replace(/×/g,"*").replace(/÷/g,"/").replace(/−/g,"-"))throw Error("invalid");let pos=0;function factor(){const t=tokens[pos++];if(t==="-")return -factor();if(t==="+")return factor();if(t==="("){const v=expr();if(tokens[pos++]!==")")throw Error("paren");return v;}const n=Number(t);if(!Number.isFinite(n))throw Error("number");return n;}function term(){let v=factor();while(tokens[pos]==="*"||tokens[pos]==="/"){const op=tokens[pos++],n=factor();if(op==="/"&&n===0)throw Error("zero");v=op==="*"?v*n:v/n;}return v;}function expr(){let v=term();while(tokens[pos]==="+"||tokens[pos]==="-"){const op=tokens[pos++],n=term();v=op==="+"?v+n:v-n;}return v;}const result=expr();if(pos!==tokens.length||!Number.isFinite(result))throw Error("invalid");return Math.round(result*1e8)/1e8;}
function updateCalc(key){if(key==="clear")calcExpression="";else if(key==="back")calcExpression=calcExpression.slice(0,-1);else if(key==="equals"){try{const res=calculate(calcExpression);calcExpression=String(res);}catch(_){showToast("تحقق من العملية الحسابية.");} }else calcExpression+=key;$("#calcDisplay").value=calcExpression||"0";}
const unitFactors={km:{type:"distance",factor:1000},m:{type:"distance",factor:1},cm:{type:"distance",factor:.01},kg:{type:"mass",factor:1000},g:{type:"mass",factor:1}};
function convertUnits(){const val=Number($("#unitValue").value)||0,from=unitFactors[$("#unitFrom").value],to=unitFactors[$("#unitTo").value];if(from.type!==to.type){$("#unitResult").textContent="—";return;}$("#unitResult").textContent=String(Number((val*from.factor/to.factor).toPrecision(8)));}
function startMemoryGame(){const icons=["◉","△","✦","π","⌘","◇","☼","♧"];const deck=icons.concat(icons).sort(()=>Math.random()-.5);let first=null,lock=false,matches=0,moves=0;const host=$("#gameStage");host.innerHTML='<div class="panel-heading"><div><h3>تحدي الذاكرة</h3><p>اعثر على الأزواج المتشابهة.</p></div><span class="task-total" id="memoryMoves">محاولات: 0</span></div><div class="memory-grid">'+deck.map((_,i)=>'<button class="memory-tile" data-memory="'+i+'">?</button>').join("")+'</div><div class="game-status" id="memoryStatus">اعثر على جميع الأزواج الثمانية.</div>';$$("[data-memory]",host).forEach(btn=>btn.addEventListener("click",()=>{if(lock||btn.classList.contains("matched")||btn.classList.contains("open"))return;const i=Number(btn.dataset.memory);btn.textContent=deck[i];btn.classList.add("open");if(first===null){first=btn;return;}moves++;$("#memoryMoves").textContent="محاولات: "+moves;if(first.textContent===btn.textContent){first.classList.add("matched");btn.classList.add("matched");first=null;matches++;if(matches===8)$("#memoryStatus").textContent="رائع! أكملت اللعبة في "+moves+" محاولة.";}else{lock=true;const old=first;first=null;setTimeout(()=>{old.textContent="?";btn.textContent="?";old.classList.remove("open");btn.classList.remove("open");lock=false;},700);}}));}
function nextMathQuestion(){mathQuestion++;const a=Math.floor(Math.random()*12)+2,b=Math.floor(Math.random()*12)+2;const op=["+","−","×"][Math.floor(Math.random()*3)];const result=op==="+"?a+b:op==="−"?a-b:a*b;const host=$("#gameStage");host.innerHTML='<div class="math-challenge"><span class="tiny-status">MATH CHALLENGE</span><p>النقاط: <strong id="mathScore">'+mathScore+'</strong></p><strong>'+a+" "+op+" "+b+' = ؟</strong><form class="math-answer" id="mathForm"><input id="mathInput" type="number" required placeholder="إجابتك"><button class="primary-button">تحقق</button></form><p class="game-status" id="mathStatus">السؤال '+mathQuestion+'</p></div>';$("#mathForm").addEventListener("submit",e=>{e.preventDefault();const val=Number($("#mathInput").value);if(val===result){mathScore++;showToast("إجابة صحيحة!");}else showToast("الإجابة الصحيحة هي "+result);setTimeout(nextMathQuestion,650);});}
